package com.lianxibu.site.service.content;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;
import com.lianxibu.site.service.jobs.SharedWriteExecutor;
import java.time.*;import java.util.*;
import javax.sql.DataSource;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

class GeneratedContentServiceTest {
 DataSource source;JdbcTemplate jdbc;SharedWriteExecutor writes;GeneratedContentService service;
 final Clock clock=Clock.fixed(Instant.parse("2026-01-02T00:00:00.123456Z"),ZoneOffset.UTC);
 static final String BODY="{\"title\":\"Fictional report\",\"sections\":[{\"heading\":\"Fictional section\",\"text\":\"Fictional text\",\"citation_ids\":[]}],\"citation_ids\":[],\"type\":\"daily\",\"period_start\":\"2025-12-31T16:00:00.000000Z\",\"period_end\":\"2026-01-01T16:00:00.000000Z\",\"timezone\":\"Asia/Shanghai\",\"learning_task\":null}";
 static final String DDL="CREATE TABLE contents(kind VARCHAR(16) NOT NULL,id VARCHAR(64) NOT NULL,natural_key VARCHAR(255) NOT NULL,title VARCHAR(512) NOT NULL,body_json CLOB NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,body_revision BIGINT,published_at TIMESTAMP,input_job_id VARCHAR(64),entity_id VARCHAR(64),period_key_hash BINARY(32) UNIQUE,body_hash_v1 BINARY(32),review_hash BINARY(32),review_hash_v1 BINARY(32),review_dependency_stamp CLOB,review_stamp_hash BINARY(32),review_stamp_id VARCHAR(64),reviewed_input_hash BINARY(32),blocking_summary_json CLOB,content_key_json CLOB,updated_at TIMESTAMP NOT NULL,PRIMARY KEY(kind,id),UNIQUE(kind,natural_key))";
 @BeforeEach void fixture(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:generated-content-"+System.nanoTime()+";DB_CLOSE_DELAY=-1;MODE=MySQL");source=ds;setup(false);}
 void setup(boolean mysql){jdbc=new JdbcTemplate(source);jdbc.execute("CREATE TABLE worker_lock(id INT PRIMARY KEY)");jdbc.update("INSERT INTO worker_lock VALUES(1)");jdbc.execute(mysql?DDL.replace("CLOB","JSON").replace("TIMESTAMP","DATETIME(6)")+" ENGINE=InnoDB":DDL);service=new GeneratedContentService(new JdbcGeneratedContents(source),clock);writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(source),new DataSourceTransactionManager(source),()->25,n->{});}
 GeneratedContentService.Write command(String id,Long expected,String body){return new GeneratedContentService.Write("report",id,expected,"fictional-input",body);}
 JdbcGeneratedContents.Applied apply(String key,GeneratedContentService.Write cmd){return writes.execute(new SharedWriteExecutor.ActionContext(key,"fictional-owner","a".repeat(64)),k->null,a->{var applied=service.write(cmd);return new Box(applied);}).value;}
 record Box(JdbcGeneratedContents.Applied value){}
 @Test void replacementSeparatesBodyRevisionAndClearsOnlyV1ReviewWhilePreservingNaturalIdentity(){var created=apply("fictional-create",command("fictional-report",null,BODY));assertEquals(1,created.revision());var before=new JdbcContentReads(source).current("report","fictional-report");jdbc.update("UPDATE contents SET revision=5,state='published',review_hash=?,review_hash_v1=?,review_stamp_hash=?,review_stamp_id='fictional-stamp',review_dependency_stamp='{}',reviewed_input_hash=?,published_at=?",new byte[32],new byte[32],new byte[32],new byte[32],java.sql.Timestamp.from(clock.instant()));var replaced=apply("fictional-replace",command("fictional-report",5L,BODY.replace("Fictional text","Fictional changed")));assertEquals(6,replaced.revision());assertEquals(2,replaced.bodyRevision());var after=new JdbcContentReads(source).current("report","fictional-report");assertEquals(before.naturalKey(),after.naturalKey());assertEquals("draft",after.state());assertNull(after.reviewStampHash());assertNull(after.reviewDependencyStamp());assertNull(after.publishedAt());assertArrayEquals(new byte[32],jdbc.queryForObject("SELECT review_hash FROM contents",byte[].class));assertEquals(CanonicalJson.hash(CanonicalJson.Domain.CONTENT,CanonicalJson.parse(after.bodyJson())),HexFormat.of().formatHex(after.bodyHashV1()));}
 @Test void staleVersionWrongPeriodAndDuplicatePeriodDoNotOverwriteOrSelectAnotherContent(){apply("fictional-create",command("fictional-report",null,BODY));assertNull(apply("fictional-stale",command("fictional-report",4L,BODY)));assertNull(apply("fictional-duplicate-period",command("fictional-other",null,BODY)));assertNull(apply("fictional-other-period",command("fictional-report",1L,BODY.replace("2025-12-31","2026-01-01").replace("2026-01-01T16:00:00.000000Z\",\"timezone","2026-01-02T16:00:00.000000Z\",\"timezone"))));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM contents",Integer.class));assertEquals(1,new JdbcContentReads(source).current("report","fictional-report").revision());}
 @Test void downstreamFailureRollsBackBodyAndMalformedOrOutOfTransactionWriteIsRejected(){assertThrows(RuntimeException.class,()->writes.execute(new SharedWriteExecutor.ActionContext("fictional-rollback","fictional-owner","a".repeat(64)),k->null,a->{service.write(command("fictional-report",null,BODY));throw new IllegalStateException("fictional downstream failure");}));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM contents",Integer.class));assertThrows(IllegalStateException.class,()->service.write(command("fictional-report",null,BODY)));assertThrows(IllegalArgumentException.class,()->service.write(command("fictional-report",null,BODY.replace("\"type\":\"daily\"","\"type\":\"unknown\""))));}
 @Test void analysisEntityAndBusinessKindAreExact(){String body="{\"title\":\"Fictional agent\",\"sections\":[],\"citation_ids\":[],\"category\":\"agent\",\"entity_id\":\"fictional-entity\"}";var cmd=new GeneratedContentService.Write("agent","fictional-agent",null,"fictional-input",body);assertEquals(1,apply("fictional-agent-create",cmd).revision());assertNull(apply("fictional-entity-mismatch",new GeneratedContentService.Write("agent","fictional-agent",1L,"fictional-input",body.replace("fictional-entity","fictional-other"))));assertThrows(IllegalArgumentException.class,()->service.write(new GeneratedContentService.Write("skill","fictional-agent",1L,"fictional-input",body)));}
}
